class BoundedCache:
    """At most `max_entries` values, each fresh for `ttl_seconds`."""

    def __init__(self, ttl_seconds: float, max_entries: int, clock) -> None:
        self.ttl_seconds = ttl_seconds
        self.max_entries = max_entries
        self.clock = clock
        self.store = {}  # key -> (value, stored_at)
        self.evictions = 0

    def _expired(self, stored_at: float) -> bool:
        return (self.clock() - stored_at) > self.ttl_seconds

    def get(self, key):
        item = self.store.get(key)
        if item is None:
            return None
        value, stored_at = item
        if self._expired(stored_at):
            del self.store[key]
            return None
        return value

    def put(self, key, value) -> None:
        if key not in self.store and len(self.store) >= self.max_entries:
            self._make_room()
        self.store[key] = (value, self.clock())

    def _make_room(self) -> None:
        stale = [k for k, (_, stored_at) in self.store.items() if self._expired(stored_at)]
        if stale:
            for k in stale:
                del self.store[k]
            return
        oldest = min(self.store, key=lambda k: self.store[k][1])
        del self.store[oldest]
        self.evictions += 1
